import React, { useState, useEffect } from 'react';
import { useOutletContext } from 'react-router-dom';

const ATS_P4 = () => {
  const context = useOutletContext();
  const [displayData, setDisplayData] = useState(context?.ats?.data);

  // This ensures that when the data finally arrives through the context, 
  // the component re-renders to show it.
  useEffect(() => {
    if (context?.ats?.data) {
      setDisplayData(context.ats.data);
    }
  }, [context?.ats?.data]);

  if (!displayData) {
    return <div className="summary-box">Waiting for data stream...</div>;
  }

  return (
    <div className="summary-box">
      <h3>Persistence & System Telemetry</h3>
      <div className="telemetry-log p-4 bg-black text-green-400 font-mono text-sm rounded">
        <p>{'>'} System Initialized...</p>
        <p>{'>'} Sync Status: {displayData.db_synced ? "COMMITTED" : "PENDING"}</p>
        <p>{'>'} Vector Index: {displayData.vector_id || "NOT_INDEXED"}</p>
        <p>{'>'} Total Ops Time: {displayData.processing_time || 0}ms</p>
      </div>
    </div>
  );
};
export default ATS_P4;
